DO $$ DECLARE existing_rule text; BEGIN SELECT pg_get_constraintdef(oid) INTO existing_rule FROM pg_constraint WHERE conrelid = 'public.v3_installment_orders'::regclass AND conname = 'v3_installment_orders_plan_check'; IF existing_rule IS NULL THEN RAISE EXCEPTION 'Existing plan constraint missing'; END IF; EXECUTE 'ALTER TABLE public.v3_installment_orders DROP CONSTRAINT v3_installment_orders_plan_check'; EXECUTE 'ALTER TABLE public.v3_installment_orders ADD CONSTRAINT v3_installment_orders_plan_check CHECK (plan = ''pack_mockup_3d'' OR ' || substring(existing_rule FROM 7) || ')'; END $$;